using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using BuildingFlow.Application;
namespace BuildingFlow.Infrastructure;
// DNS requests go only to a fixed HTTPS resolver. TLS probes pin a checked public address at connect time.
public sealed class WebsiteDomainVerifier:IWebsiteDomainVerifier{
 public static bool PublicAddress(IPAddress ip){if(ip.IsIPv4MappedToIPv6)ip=ip.MapToIPv4();if(IPAddress.IsLoopback(ip))return false;var b=ip.GetAddressBytes();if(b.Length==4)return b[0]!=0&&b[0]!=10&&b[0]!=127&&b[0]<224&&!(b[0]==100&&b[1]>=64&&b[1]<=127)&&!(b[0]==169&&b[1]==254)&&!(b[0]==172&&b[1]>=16&&b[1]<=31)&&!(b[0]==192&&(b[1]==168||b[1]==0||b[1]==2))&&!(b[0]==198&&(b[1]==18||b[1]==19||b[1]==51))&&!(b[0]==203&&b[1]==0&&b[2]==113);return (b[0]&0xe0)==0x20&&!(b[0]==0x20&&b[1]==1&&(b[2]==0x0d&&b[3]==0xb8||b[2]==0&&b[3]==0));}
 public static bool TxtMatches(string json,string name,string hash){using var doc=JsonDocument.Parse(json);var root=doc.RootElement;if(!root.TryGetProperty("Status",out var status)||status.GetInt32()!=0||!root.TryGetProperty("Answer",out var answers)||answers.ValueKind!=JsonValueKind.Array)return false;foreach(var answer in answers.EnumerateArray()){if(!answer.TryGetProperty("type",out var type)||type.GetInt32()!=16||!answer.TryGetProperty("name",out var n)||!string.Equals(n.GetString()?.TrimEnd('.'),name,StringComparison.OrdinalIgnoreCase)||!answer.TryGetProperty("data",out var d))continue;var text=d.GetString()??"";if(text.Length==66&&text[0]=='"'&&text[^1]=='"')text=text[1..^1];if(text.Length==64&&text.All(c=>c is >= '0' and <= '9' or >= 'a' and <= 'f')&&WebsiteImage.Sha(Encoding.UTF8.GetBytes(text))==hash)return true;}return false;}
 public async Task<(bool Dns,bool Tls)> Check(string host,string tokenHash,CancellationToken t){try{host=BuildingFlow.Domain.WebsiteDomain.Normalize(host);using var timeout=CancellationTokenSource.CreateLinkedTokenSource(t);timeout.CancelAfter(TimeSpan.FromSeconds(12));var name="_buildingflow-verify."+host;using var handler=new HttpClientHandler{AllowAutoRedirect=false,UseCookies=false,UseProxy=false};using var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(5)};using var req=new HttpRequestMessage(HttpMethod.Get,"https://cloudflare-dns.com/dns-query?name="+Uri.EscapeDataString(name)+"&type=TXT");req.Headers.Accept.ParseAdd("application/dns-json");using var response=await http.SendAsync(req,HttpCompletionOption.ResponseHeadersRead,timeout.Token);if(!response.IsSuccessStatusCode)return(false,false);await using var stream=await response.Content.ReadAsStreamAsync(timeout.Token);using var data=new MemoryStream();var buffer=new byte[4096];int count;while((count=await stream.ReadAsync(buffer,timeout.Token))>0){if(data.Length+count>65536)return(false,false);data.Write(buffer,0,count);}if(!TxtMatches(Encoding.UTF8.GetString(data.ToArray()),name,tokenHash))return(false,false);
 using var tlsHandler=new SocketsHttpHandler{AllowAutoRedirect=false,UseCookies=false,UseProxy=false,ConnectCallback=async(ctx,ct)=>{if(ctx.DnsEndPoint.Port!=443||ctx.DnsEndPoint.Host!=host)throw new HttpRequestException("Invalid TLS destination.");var ips=await Dns.GetHostAddressesAsync(host,ct);if(ips.Length==0||ips.Any(ip=>!PublicAddress(ip)))throw new HttpRequestException("Non-public TLS destination.");var socket=new Socket(ips[0].AddressFamily,SocketType.Stream,ProtocolType.Tcp);try{await socket.ConnectAsync(new IPEndPoint(ips[0],443),ct);return new NetworkStream(socket,true);}catch{socket.Dispose();throw;}}};using var tls=new HttpClient(tlsHandler){Timeout=TimeSpan.FromSeconds(5)};using var result=await tls.SendAsync(new HttpRequestMessage(HttpMethod.Head,"https://"+host+"/"),HttpCompletionOption.ResponseHeadersRead,timeout.Token);return(true,true);
 }catch(Exception e)when(e is HttpRequestException or SocketException or OperationCanceledException or JsonException or ArgumentException or InvalidOperationException){if(t.IsCancellationRequested)throw;return(false,false);}}
}
